// dev4 hollow-ride audit: top-down height map (0.3 m cells) of a ride's up-facing triangles; pit = share of interior cells lying > 0.5 m below something within 0.9 m (an open-top deck / empty bed = high, a roofed body = low)
function CK_pit(m){m.updateMatrixWorld(true);const inv=new THREE.Matrix4().copy(m.matrixWorld).invert(),cell=.3,map=new Map();let H=-1e9,minY=1e9;const A=new THREE.Vector3(),B=new THREE.Vector3(),C=new THREE.Vector3(),mm=new THREE.Matrix4(),im=new THREE.Matrix4(),n=new THREE.Vector3(),e1=new THREE.Vector3(),e2=new THREE.Vector3();let tris=0;
 m.traverse(o=>{if(!o.isMesh||!o.geometry||!o.geometry.attributes.position)return;let v=o;while(v&&v!==m){if(v.visible===false||v.userData.ofSeat)return;v=v.parent}if(o.visible===false)return;const P=o.geometry.attributes.position,I=o.geometry.index,cnt=I?I.count:P.count,N=o.isInstancedMesh?o.count:1;o.updateMatrixWorld(true);
  for(let k=0;k<N;k++){if(o.isInstancedMesh){o.getMatrixAt(k,im);mm.multiplyMatrices(inv,o.matrixWorld).multiply(im)}else mm.multiplyMatrices(inv,o.matrixWorld);
   for(let i=0;i<cnt;i+=3){const a=I?I.getX(i):i,b2=I?I.getX(i+1):i+1,c=I?I.getX(i+2):i+2;A.fromBufferAttribute(P,a).applyMatrix4(mm);B.fromBufferAttribute(P,b2).applyMatrix4(mm);C.fromBufferAttribute(P,c).applyMatrix4(mm);tris++;
    minY=Math.min(minY,A.y,B.y,C.y);H=Math.max(H,A.y,B.y,C.y);e1.subVectors(B,A);e2.subVectors(C,A);n.crossVectors(e1,e2);if(n.y<=0||n.y<n.length()*.5)continue;
    const xa=Math.min(A.x,B.x,C.x),xb=Math.max(A.x,B.x,C.x),za=Math.min(A.z,B.z,C.z),zb=Math.max(A.z,B.z,C.z),y=Math.max(A.y,B.y,C.y);
    for(let gx=Math.floor(xa/cell);gx<=Math.floor(xb/cell);gx++)for(let gz=Math.floor(za/cell);gz<=Math.floor(zb/cell);gz++){const key=gx*10000+gz,o2=map.get(key);if(o2===undefined||y>o2)map.set(key,y)}}}});
 const h=H-minY;let low=0,tot=0,hi=0;for(const[k,y]of map){tot++;const r=(y-minY)/h;if(r<.38)low++;if(r>.7)hi++}
 let inner=0,pit=0;for(const[k,y]of map){const gx=Math.round(k/10000),gz=k-gx*10000;let full=true,mx=y;for(let dx=-1;dx<=1&&full;dx++)for(let dz=-1;dz<=1;dz++){const v=map.get((gx+dx)*10000+gz+dz);if(v===undefined){full=false;break}}if(!full)continue;inner++;for(let dx=-3;dx<=3;dx++)for(let dz=-3;dz<=3;dz++){const v=map.get((gx+dx)*10000+gz+dz);if(v!==undefined&&v>mx)mx=v}if(y<mx-.5)pit++}
 let roof=0;for(const y of map.values())if(y>=minY+.93*h)roof++;
 return{roof:+(roof/Math.max(1,tot)).toFixed(2),tris,area:+(tot*cell*cell).toFixed(1),h:+h.toFixed(2),low:+(low/Math.max(1,tot)).toFixed(2),pit:+(pit/Math.max(1,inner)).toFixed(2)}}
